const test = require('node:test');
const assert = require('node:assert/strict');
const { wrap } = require('./wrap');

test('wraps a sentence', () => {
  assert.deepEqual(wrap('the quick brown fox', 10), ['the quick', 'brown fox']);
});

test('short text stays on one line', () => {
  assert.deepEqual(wrap('hello world', 40), ['hello world']);
});

test('whitespace handling and trimming', () => {
  assert.deepEqual(wrap('  the   quick\tbrown\nfox  ', 10), ['the quick', 'brown fox']);
});

test('word longer than width gets own line', () => {
  assert.deepEqual(wrap('the extraordinaire fox', 5), ['the', 'extraordinaire', 'fox']);
});

test('empty or whitespace-only text returns empty array', () => {
  assert.deepEqual(wrap('', 10), []);
  assert.deepEqual(wrap('   \t\n  ', 10), []);
});

test('type and range errors', () => {
  assert.throws(() => wrap(123, 10), TypeError);
  assert.throws(() => wrap('abc', 0), RangeError);
  assert.throws(() => wrap('abc', -5), RangeError);
  assert.throws(() => wrap('abc', 3.5), RangeError);
  assert.throws(() => wrap('abc', '5'), RangeError);
});
"}
